(() => {
  const hero = document.querySelector('.section-24');
  if (!hero || hero.querySelector('.emt-sky')) return;

  const sky = document.createElement('div');
  sky.className = 'emt-sky';
  sky.setAttribute('aria-hidden', 'true');

  const stars = [
    { x: 10, size: 4, duration: 8.8, delay: -1.2, drift: 22, dot: true },
    { x: 23, size: 7, duration: 10.6, delay: -7.1, drift: 32 },
    { x: 38, size: 4, duration: 7.9, delay: -4.8, drift: -13, dot: true },
    { x: 54, size: 6, duration: 11.8, delay: -9.4, drift: 25 },
    { x: 68, size: 4, duration: 9.5, delay: -2.9, drift: -18, dot: true },
    { x: 81, size: 8, duration: 12.5, delay: -6.3, drift: 28 },
    { x: 92, size: 4, duration: 8.4, delay: -5.2, drift: -12, dot: true }
  ];

  stars.forEach((config) => {
    const star = document.createElement('span');
    star.className = `emt-star${config.dot ? ' emt-star--dot' : ''}`;
    star.style.setProperty('--x', `${config.x}%`);
    star.style.setProperty('--size', `${config.size}px`);
    star.style.setProperty('--duration', `${config.duration}s`);
    star.style.setProperty('--delay', `${config.delay}s`);
    star.style.setProperty('--drift', `${config.drift}px`);
    sky.appendChild(star);
  });

  const masks = {
    'image-39': [
      { mask: '0% 38%, 14% 38%, 14% 75%, 0% 75%', ox: '6%', oy: '70%' },
      { mask: '33% 47%, 44% 47%, 44% 65%, 33% 65%', ox: '38%', oy: '63%' },
      { mask: '87% 46%, 100% 46%, 100% 69%, 87% 69%', ox: '94%', oy: '67%' }
    ],
    'image-38': [
      { mask: '0% 29%, 25% 29%, 25% 80%, 0% 80%', ox: '12%', oy: '75%' },
      { mask: '36% 43%, 47% 43%, 47% 72%, 36% 72%', ox: '42%', oy: '69%' },
      { mask: '84% 28%, 100% 28%, 100% 80%, 84% 80%', ox: '94%', oy: '76%' }
    ]
  };

  const treeLayers = [];
  const syncTreeLayers = () => {
    const images = [...hero.querySelectorAll(':scope > .image-38, :scope > .image-39')];
    const source = images.find((img) => {
      const rect = img.getBoundingClientRect();
      return getComputedStyle(img).display !== 'none' && rect.width > 20 && rect.height > 20;
    });
    if (!source) return;

    const sourceClass = source.classList.contains('image-38') ? 'image-38' : 'image-39';
    const heroRect = hero.getBoundingClientRect();
    const sourceRect = source.getBoundingClientRect();

    treeLayers.forEach((layer) => layer.remove());
    treeLayers.length = 0;

    masks[sourceClass].forEach((tree, index) => {
      const layer = source.cloneNode(false);
      layer.removeAttribute('id');
      layer.removeAttribute('srcset');
      layer.removeAttribute('sizes');
      layer.className = 'emt-tree-image';
      layer.alt = '';
      layer.setAttribute('aria-hidden', 'true');
      layer.style.left = `${sourceRect.left - heroRect.left}px`;
      layer.style.top = `${sourceRect.top - heroRect.top}px`;
      layer.style.width = `${sourceRect.width}px`;
      layer.style.height = `${sourceRect.height}px`;
      layer.style.setProperty('--tree-mask', tree.mask);
      layer.style.setProperty('--origin-x', tree.ox);
      layer.style.setProperty('--origin-y', tree.oy);
      layer.style.setProperty('--sway-time', `${6.8 + index * 1.1}s`);
      layer.style.setProperty('--sway-delay', `${index * -1.7}s`);
      hero.appendChild(layer);
      treeLayers.push(layer);
    });
  };

  hero.appendChild(sky);
  requestAnimationFrame(syncTreeLayers);
  let resizeTimer;
  addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(syncTreeLayers, 150);
  }, { passive: true });

})();

(function () {
  'use strict';

  function getOpenMenus() {
    return Array.from(document.querySelectorAll('details.header-clean__mobile[open]'));
  }

  function closeMenu(menu) {
    if (!menu) return;
    menu.removeAttribute('open');
    var button = menu.querySelector('summary');
    if (button) button.setAttribute('aria-label', 'Open navigation menu');
  }

  document.addEventListener('click', function (event) {
    getOpenMenus().forEach(function (menu) {
      var clickedLink = event.target.closest('a');
      if (!menu.contains(event.target) || (clickedLink && menu.contains(clickedLink))) {
        closeMenu(menu);
      }
    });
  });

  document.addEventListener('keydown', function (event) {
    if (event.key !== 'Escape') return;
    var menus = getOpenMenus();
    menus.forEach(closeMenu);
    if (menus.length) {
      var button = menus[menus.length - 1].querySelector('summary');
      if (button) button.focus();
    }
  });

  document.addEventListener('toggle', function (event) {
    var menu = event.target;
    if (!menu.matches || !menu.matches('details.header-clean__mobile')) return;
    var button = menu.querySelector('summary');
    if (button) {
      button.setAttribute('aria-label', menu.open ? 'Close navigation menu' : 'Open navigation menu');
    }
  }, true);
})();

