      var activeAudio = activeRoot.querySelector('.emtalk-audio-player__control');
      var activeTitle = activeRoot.querySelector('.emtalk-player-ui__name');
      if (activeAudio && audioUrl) {
        activeAudio.src = audioUrl;
        activeAudio.load();
      }
      if (activeTitle && title) activeTitle.textContent = title;
      activeRoot.style.display = audioUrl ? '' : 'none';
