(function () {
  function initArticlePlayer() {
    var meta = document.querySelector('[tmplayer-meta="audio-url"]');
    var heading = document.querySelector('h1');
    var audioUrl = meta ? meta.textContent.trim() : '';
    var title = heading ? heading.textContent.trim() : '';

    var activeRoot = document.querySelector('.emtalk-audio-player');
    if (activeRoot) {
      var activeAudio = activeRoot.querySelector('.emtalk-audio-player__control');
      var activeTitle = activeRoot.querySelector('.emtalk-player-ui__name');
      if (activeAudio && audioUrl) {
        activeAudio.src = audioUrl;
        activeAudio.load();
      }
      if (activeTitle && title) activeTitle.textContent = title;
      activeRoot.style.display = audioUrl ? '' : 'none';
    }

    var script = document.currentScript;
    var legacyRoot = document.querySelector('.sp-track-wrapper');
    var player = legacyRoot && legacyRoot.querySelector('.audio-player');
    if (!player) return;
    if (!audioUrl) {
      player.style.display = 'none';
      return;
    }

    var audio = player.querySelector('#audio-player');
    var btn = player.querySelector('#play-btn');
    var fill = player.querySelector('.progress-fill');
    var currentTimeEl = player.querySelector('#current-time');
    var durationEl = player.querySelector('#duration');
    var progressBar = player.querySelector('.progress-bar');
    var legacyTitle = legacyRoot.querySelector('.sp-artist-name');

    audio.src = audioUrl;
    if (title) {
      audio.setAttribute('aria-label', title);
      if (legacyTitle) legacyTitle.textContent = title;
      if ('mediaSession' in navigator && 'MediaMetadata' in window) {
        navigator.mediaSession.metadata = new MediaMetadata({ title: title });
      }
    }

    function formatTime(time) {
      if (!Number.isFinite(time)) return '0:00';
      var minutes = Math.floor(time / 60);
      var seconds = Math.floor(time % 60).toString().padStart(2, '0');
      return minutes + ':' + seconds;
    }

    function updateProgress() {
      var ratio = audio.duration ? audio.currentTime / audio.duration : 0;
      var percent = Math.max(0, Math.min(100, ratio * 100));
      fill.style.width = percent + '%';
      progressBar.setAttribute('aria-valuenow', String(Math.round(percent)));
      currentTimeEl.textContent = formatTime(audio.currentTime);
    }

    audio.addEventListener('loadedmetadata', function () {
      durationEl.textContent = formatTime(audio.duration);
    });
    audio.addEventListener('durationchange', function () {
      durationEl.textContent = formatTime(audio.duration);
    });
    audio.addEventListener('timeupdate', updateProgress);
    audio.addEventListener('play', function () {
      btn.textContent = '❚❚';
      btn.setAttribute('aria-label', 'Pause audio');
    });
    audio.addEventListener('pause', function () {
      btn.textContent = '▶';
      btn.setAttribute('aria-label', 'Play audio');
    });
    audio.addEventListener('ended', function () {
      btn.textContent = '▶';
    });
    btn.addEventListener('click', function () {
      if (audio.paused) {
        audio.play().catch(function (error) {
          console.error('Audio playback failed:', error);
        });
      } else {
        audio.pause();
      }
    });
    progressBar.addEventListener('click', function (event) {
      if (!audio.duration) return;
      var rect = progressBar.getBoundingClientRect();
      var ratio = Math.max(0, Math.min(1, (event.clientX - rect.left) / rect.width));
      audio.currentTime = ratio * audio.duration;
    });
    progressBar.addEventListener('keydown', function (event) {
      if (event.key !== 'ArrowRight' && event.key !== 'ArrowLeft') return;
      event.preventDefault();
      var delta = event.key === 'ArrowRight' ? 5 : -5;
      audio.currentTime = Math.max(0, Math.min(audio.duration || 0, audio.currentTime + delta));
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initArticlePlayer);
  } else {
    initArticlePlayer();
  }
})();

(function () {
  'use strict';

  function getOpenMenus() {
    return Array.from(document.querySelectorAll('details.header-clean__mobile[open]'));
  }

  function closeMenu(menu) {
    if (!menu) return;
    menu.removeAttribute('open');
    var button = menu.querySelector('summary');
    if (button) button.setAttribute('aria-label', 'Open navigation menu');
  }

  document.addEventListener('click', function (event) {
    getOpenMenus().forEach(function (menu) {
      var clickedLink = event.target.closest('a');
      if (!menu.contains(event.target) || (clickedLink && menu.contains(clickedLink))) {
        closeMenu(menu);
      }
    });
  });

  document.addEventListener('keydown', function (event) {
    if (event.key !== 'Escape') return;
    var menus = getOpenMenus();
    menus.forEach(closeMenu);
    if (menus.length) {
      var button = menus[menus.length - 1].querySelector('summary');
      if (button) button.focus();
    }
  });

  document.addEventListener('toggle', function (event) {
    var menu = event.target;
    if (!menu.matches || !menu.matches('details.header-clean__mobile')) return;
    var button = menu.querySelector('summary');
    if (button) {
      button.setAttribute('aria-label', menu.open ? 'Close navigation menu' : 'Open navigation menu');
    }
  }, true);
})();

