    display: none !important;
  }

  .load-screen.et-star-loader {
    position: fixed;
    inset: 0;
    z-index: 1000;
    overflow: hidden;
    align-items: center;
    justify-content: center;
    background: radial-gradient(circle at 50% 38%, #39234f 0%, #24142f 44%, #160d20 100%);
    color: #fff;
  }
  .et-star-loader__sky { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
  .et-star-loader__star {
    position: absolute;
    top: -12vh;
    left: var(--x);
    width: var(--size);
    height: var(--size);
    border-radius: 50%;
    background: #fff;
    box-shadow: 0 0 8px #fff, 0 0 18px rgba(198,137,252,.85);
    opacity: 0;
    animation: et-star-fall var(--duration) linear var(--delay) infinite;
  }
  .et-star-loader__star::after {
    content: '';
    position: absolute;
    left: 50%;
    bottom: 2px;
    width: 1px;
    height: 42px;
    background: linear-gradient(to top, rgba(255,255,255,.75), transparent);
    transform: translateX(-50%);
  }
  .et-star-loader__content { position: relative; z-index: 1; width: min(440px, calc(100% - 48px)); text-align: center; }
  .et-star-loader__mark { margin-bottom: 22px; color: #fbe0f4; font-size: 32px; line-height: 1; }
  .et-star-loader__title { margin: 0 0 12px; font: 700 30px/1.2 Manrope, Arial, sans-serif; }
  .et-star-loader__text { margin: 0; color: rgba(255,255,255,.76); font: 400 17px/1.5 Manrope, Arial, sans-serif; }
  .et-star-loader__track { position: relative; height: 3px; margin-top: 32px; overflow: hidden; border-radius: 99px; background: rgba(255,255,255,.16); }
  .et-star-loader__line { position: absolute; inset: 0 auto 0 0; width: 42%; border-radius: inherit; background: linear-gradient(90deg, #c689fc, #fbe0f4, #fff); box-shadow: 0 0 14px rgba(198,137,252,.85); animation: et-hope-line 1.8s ease-in-out infinite; }
  @keyframes et-star-fall {
    0% { opacity: 0; transform: translate3d(0,-8vh,0) scale(.7); }
    10% { opacity: .9; }
    84% { opacity: .75; }
    100% { opacity: 0; transform: translate3d(24px,120vh,0) scale(1.05); }
  }
  @keyframes et-hope-line {
    0% { transform: translateX(-110%); }
    55%, 100% { transform: translateX(340%); }
  }
  @media (prefers-reduced-motion: reduce) {
    .et-star-loader__star { display: none; animation: none; }
    .et-star-loader__line { width: 100%; animation: none; transform: none; }
  }
